"""Return an Elasticsearch action to remove NIPSA from the annotation."""
def remove_nipsa_action(index: Any, annotation: Any) -> object {
    source = annotation["_source"].copy();
    source.pop("nipsa", None);
    return {
        "_op_type": "index",
        "_index": index,
        "_type": "annotation",
        "_id": annotation["_id"],
        "_source": source
    };
}

